"use strict";

const synthetics = require("@aws/synthetics-puppeteer");
const log = require("SyntheticsLogger");

const { requireEnv, getBooleanEnv } = require("./config/env");
const { applyGlobalSyntheticsConfig } = require("./config/syntheticsConfig");
const { createHttpHelpers } = require("./lib/http");
const { getDefaultHttpStepConfig } = require("./data/formData");
const { createRunContext } = require("./flows/context");

const loginFlow = require("./flows/loginFlow");
const profileFlow = require("./flows/profileFlow");
const patientFlow = require("./flows/patientFlow");
const usersDoctorsFlow = require("./flows/usersDoctorsFlow");
const caseFlow = require("./flows/caseFlow");
const appointmentFlow = require("./flows/appointmentFlow");
const templateFlow = require("./flows/templateFlow");
const quickNoteFlow = require("./flows/quickNoteFlow");
const conversationFlow = require("./flows/conversationFlow");

const syntheticsConfiguration = synthetics.getConfiguration();

/**
 * Orchestration only: configure Synthetics, build shared deps, run flows in order.
 */
async function apiCanaryBlueprint() {
  applyGlobalSyntheticsConfig(syntheticsConfiguration);

  const { resolveApiUrl, urlToHttpStepOptions, createWithAuth } = createHttpHelpers(requireEnv);
  const ctx = createRunContext();
  const withAuth = createWithAuth(synthetics, ctx);
  const stepConfig = getDefaultHttpStepConfig();

  const deps = {
    synthetics,
    log,
    stepConfig,
    resolveApiUrl,
    urlToHttpStepOptions,
    withAuth,
    ctx,
  };

  await loginFlow.run(deps, {
    email: requireEnv("LOGIN_EMAIL"),
    password: requireEnv("LOGIN_PASSWORD"),
  });

  await profileFlow.run(deps);
  await patientFlow.run(deps);
  await patientFlow.runGetAndUpdate(deps);
  await usersDoctorsFlow.run(deps);
  await caseFlow.runCreate(deps);
  await caseFlow.runListIfNeeded(deps);
  await caseFlow.runGetAndUpdate(deps);
  await appointmentFlow.runCreate(deps);
  await appointmentFlow.runGetAndUpdate(deps);
  await conversationFlow.runCreateGetUpdate(deps, {
    skipOnForbidden: getBooleanEnv("SKIP_CONVERSATION_ON_FORBIDDEN", true),
    skipIfUnresolved: getBooleanEnv("SKIP_CONVERSATION_IF_UNRESOLVED", true),
  });
  await templateFlow.runCreateConversationDefault(deps);
  await templateFlow.runCreateAppealLetter(deps);
  await templateFlow.runGetAndUpdate(deps);
  await quickNoteFlow.runCreateAndGet(deps);
  await quickNoteFlow.runUpdate(deps);

  if (!ctx.caseUid) {
    throw new Error("case uid not resolved after create/list");
  }

  log.info(
    "canary-flow-complete: patientUid=" +
      String(ctx.patientUid) +
      " caseUid=" +
      String(ctx.caseUid) +
      " appointmentUid=" +
      String(ctx.appointmentUid) +
      " conversationTemplateUid=" +
      String(ctx.conversationTemplateUid) +
      " appealLetterTemplateUid=" +
      String(ctx.appealLetterTemplateUid) +
      " quickNoteUid=" +
      String(ctx.quickNoteUid) +
      " conversationUid=" +
      String(ctx.conversationUid)
  );
}

exports.handler = async () => {
  return await apiCanaryBlueprint();
};
